<script setup>
import { computed, inject, ref } from 'vue';
import { useForm } from '@inertiajs/vue3';
import { formatMoney, formatDateOnly } from '@/Utils/format';
import { PlusIcon, PencilIcon, TrashIcon } from '@heroicons/vue/24/outline';
const props = defineProps({ trip: Object, categories: Array });
const emit = defineEmits(['delete']);
const route = inject('route');
const open = ref(false);
const editingId = ref(null);
const editable = computed(() => props.trip.estado === 'activo');
const rules = { value: 'Valor de compra', units: 'Unidades', weight: 'Peso', volume: 'Volumen', direct: 'Producto específico' };
const form = useForm({ expense_category_id: '', concepto: '', moneda: props.trip.moneda_trabajo, monto: '', rate_mode: 'estimated', applied_rate: '', rate_source: '', rate_date: '', allocation_method: 'value', target_product_id: '', comprobante: null, eliminar_comprobante: false, expected_revision: props.trip.revision });
const add = () => { form.reset(); form.clearErrors(); form.expected_revision = props.trip.revision; editingId.value = null; open.value = true; };
const edit = expense => { form.clearErrors(); Object.assign(form, { expense_category_id: expense.expense_category_id || '', concepto: expense.concepto, moneda: expense.moneda, monto: expense.monto, rate_mode: expense.rate_mode, applied_rate: expense.applied_rate || '', rate_source: expense.rate_source === 'legacy-unverified' ? '' : expense.rate_source || '', rate_date: expense.rate_date || '', allocation_method: expense.allocation_method, target_product_id: expense.target_product_id || '', comprobante: null, eliminar_comprobante: false, expected_revision: props.trip.revision }); editingId.value = expense.id; open.value = true; };
const close = () => { if (!form.processing) { open.value = false; editingId.value = null; } };
const submit = () => {
    const options = { forceFormData: true, preserveScroll: true, onSuccess: () => { open.value = false; form.reset(); } };
    form.transform(data => ({ ...data, ...(editingId.value ? { _method: 'put' } : {}) })).post(editingId.value ? route('trips.expenses.update', [props.trip.id, editingId.value]) : route('trips.expenses.store', props.trip.id), options);
};
</script>
<template>
    <section class="f-panel"><div class="f-panel-heading"><div><h2>Gastos de importación</h2><p class="f-hint">{{ trip.expenses.length }} gastos · conversión y reparto explícitos</p></div><button v-if="editable" class="f-button f-button-primary" @click="add"><PlusIcon /> Agregar gasto</button></div>
        <form v-if="open" class="f-panel-body" @submit.prevent="submit"><h3 style="font-weight:600;margin-bottom:16px">{{ editingId ? 'Editar gasto' : 'Nuevo gasto' }}</h3><div class="f-form-grid">
            <div class="f-field"><label for="expense-concept">Concepto</label><input id="expense-concept" class="f-input" v-model="form.concepto" required maxlength="255" /><span class="f-field-error">{{ form.errors.concepto }}</span></div><div class="f-field"><label for="expense-category">Categoría</label><select id="expense-category" class="f-input" v-model="form.expense_category_id"><option value="">Sin categoría</option><option v-for="category in categories" :key="category.id" :value="category.id">{{ category.nombre }}</option></select><span class="f-field-error">{{ form.errors.expense_category_id }}</span></div>
            <div class="f-field"><label for="expense-currency">Moneda original</label><select id="expense-currency" class="f-input" v-model="form.moneda"><option :value="trip.moneda_trabajo">{{ trip.moneda_trabajo }}</option><option value="CLP">CLP</option></select></div><div class="f-field"><label for="expense-amount">Monto original · {{ form.moneda }}</label><input id="expense-amount" class="f-input" type="number" v-model="form.monto" min="0" step="0.01" required /><span class="f-field-error">{{ form.errors.monto }}</span></div>
            <div class="f-field"><label for="expense-rate-mode">Conversión</label><select id="expense-rate-mode" class="f-input" v-model="form.rate_mode"><option value="estimated">Estimado: usar tasa de referencia</option><option value="paid">Pagado: conservar tasa histórica</option></select><p class="f-hint">{{ form.rate_mode === 'paid' ? 'La tasa del pago se conserva al revaluar la importación.' : `La referencia actual es ${trip.tipo_cambio} CLP / ${trip.moneda_trabajo}.` }}</p></div><div class="f-field"><label for="expense-method">Distribuir por</label><select id="expense-method" class="f-input" v-model="form.allocation_method"><option v-for="(label, value) in rules" :value="value" :key="value">{{ label }}</option></select><span class="f-field-error">{{ form.errors.allocation_method }}</span><p v-if="form.allocation_method === 'weight' || form.allocation_method === 'volume'" class="f-hint">Todas las líneas necesitan su {{ form.allocation_method === 'weight' ? 'peso total en kg' : 'volumen total en m³' }}. No se sustituye una medida ausente por cero.</p></div>
            <template v-if="form.rate_mode === 'paid'"><div class="f-field"><label for="expense-paid-rate">Tasa histórica · CLP / {{ form.moneda }}</label><input id="expense-paid-rate" class="f-input" type="number" v-model="form.applied_rate" min="0.00000001" max="1000000" step="0.00000001" required /><span class="f-field-error">{{ form.errors.applied_rate }}</span></div><div class="f-field"><label for="expense-rate-source">Fuente de la tasa</label><input id="expense-rate-source" class="f-input" v-model="form.rate_source" placeholder="Comprobante bancario, factura…" required /><span class="f-field-error">{{ form.errors.rate_source }}</span></div><div class="f-field"><label for="expense-rate-date">Fecha del pago</label><input id="expense-rate-date" class="f-input" type="date" v-model="form.rate_date" required /><span class="f-field-error">{{ form.errors.rate_date }}</span></div></template>
            <div v-if="form.allocation_method === 'direct'" class="f-field"><label for="expense-target">Producto que recibe el gasto</label><select id="expense-target" class="f-input" v-model="form.target_product_id" required><option value="">Selecciona un producto</option><option v-for="product in trip.products" :value="product.id" :key="product.id">{{ product.nombre }}</option></select><span class="f-field-error">{{ form.errors.target_product_id }}</span></div>
            <div class="f-field"><label for="expense-receipt">Comprobante (opcional)</label><input id="expense-receipt" class="f-input" type="file" accept="application/pdf,image/jpeg,image/png,image/webp" @change="form.comprobante = $event.target.files[0]" /><p class="f-hint">PDF, JPEG, PNG o WebP · hasta 10 MB.</p><span class="f-field-error">{{ form.errors.comprobante }}</span></div>
        </div><div class="f-actions" style="margin-top:20px"><button type="button" class="f-button" @click="close" :disabled="form.processing">Cancelar</button><button type="submit" class="f-button f-button-primary" :disabled="form.processing">{{ form.processing ? 'Guardando…' : 'Guardar gasto' }}</button></div></form>
        <template v-if="trip.expenses.length"><div class="f-table-scroll f-desktop-table"><table class="f-table"><caption class="sr-only">Gastos con importe original, conversión y regla de reparto</caption><thead><tr><th>Gasto</th><th>Conversión</th><th>Reparto</th><th class="f-numeric">Original</th><th class="f-numeric">Monto · CLP</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody><tr v-for="expense in trip.expenses" :key="expense.id"><td><strong class="f-table-title">{{ expense.concepto }}</strong><span class="f-table-subtitle">{{ expense.category?.nombre || 'Sin categoría' }}</span></td><td><span class="f-status" :class="{ 'f-status-closed': expense.rate_mode === 'paid' }">{{ expense.rate_mode === 'paid' ? 'Pagado' : 'Estimado' }}</span><span v-if="expense.rate_mode === 'paid'" class="f-table-subtitle">{{ expense.applied_rate }} · {{ formatDateOnly(expense.rate_date, { month:'short' }) }}</span></td><td>{{ rules[expense.allocation_method] }}</td><td class="f-numeric">{{ formatMoney(expense.monto,2) }} {{ expense.moneda }}</td><td class="f-numeric"><strong>${{ formatMoney(expense.monto_clp) }}</strong></td><td><div v-if="editable" class="f-actions"><button class="f-icon-button" @click="edit(expense)" :aria-label="`Editar ${expense.concepto}`"><PencilIcon /></button><button class="f-icon-button" @click="emit('delete', expense)" :aria-label="`Eliminar ${expense.concepto}`"><TrashIcon /></button></div></td></tr></tbody></table></div><div class="f-mobile-cards"><article v-for="expense in trip.expenses" :key="expense.id" class="f-mobile-card"><div class="f-mobile-card-top"><div><strong class="f-table-title">{{ expense.concepto }}</strong><span class="f-table-subtitle">{{ expense.category?.nombre || 'Sin categoría' }} · {{ rules[expense.allocation_method] }}</span></div><span class="f-status">{{ expense.rate_mode === 'paid' ? 'Pagado' : 'Estimado' }}</span></div><div class="f-mobile-card-bottom"><span class="f-hint">{{ formatMoney(expense.monto,2) }} {{ expense.moneda }}</span><strong>${{ formatMoney(expense.monto_clp) }}</strong></div><div v-if="editable" class="f-actions" style="margin-top:12px"><button class="f-button" @click="edit(expense)">Editar gasto</button><button class="f-button f-button-danger" @click="emit('delete', expense)">Eliminar</button></div></article></div></template><div v-else class="f-empty"><h2>Los gastos completan tu costo</h2><p>Registra transporte, aduana, flete u otros costos de esta importación.</p><button v-if="editable" class="f-button" @click="add">Agregar primer gasto</button></div>
    </section>
</template>
